class BankAccount{private int accountNumber;private double balance;BankAccount(int n,double b){accountNumber=n;balance=b;}void withdraw(double a){if(a<=0)throw new IllegalArgumentException("Amount must be positive.");if(a>balance)throw new IllegalArgumentException("Insufficient balance.");balance-=a;System.out.println("Remaining balance: "+balance);}void display(){System.out.println("Account: "+accountNumber+" Balance: "+balance);}}public class Q8_Bank_Account_Withdrawal_Exception{public static void main(String[]x){BankAccount a=new BankAccount(1001,5000);try{a.withdraw(2000);a.withdraw(4000);}catch(IllegalArgumentException e){System.out.println("Error: "+e.getMessage());}finally{System.out.println("Withdrawal operation completed.");a.display();}}}
